# ---------- 09:00:00 ~ 09:02:00 (902 전략) ----------
elif 시분초 < 90200:
    if not (1000 < 현재가 <= 50000):
        매수 = False
    elif not (1.0 < 등락율 <= 8.0):
        매수 = False
    elif not (고저평균대비등락율 > 0):
        매수 = False
    elif not (현재가 < VI아래5호가):
        매수 = False
    elif 라운드피겨위5호가이내:
        매수 = False
    # 초당거래대금 필터는 주석 처리 (원본 동일)
    elif 시분초 < 90200:                         # 세부 조건
        if 시가총액 < 3000:
            if not (2.0 <= 시가등락율 < 4.0):
                매수 = False
            elif not (0.5 <= 시가대비등락율 < 6.0):
                매수 = False
            elif not (1 < 초당순매수금액 < 1000):
                매수 = False
            elif not (현재가 > (고가 - (고가 - 저가) * 0.20)):
                매수 = False
            elif not (전일비 > 0 and 전일동시간비 > 0):
                매수 = False
            elif not (1.5 < 회전율):
                매수 = False
            elif not (당일거래대금 > 5 * 100):
                매수 = False
            elif not (당일거래대금각도(30) > 5 and 당일거래대금각도(30) < 30): # 스터디 요기까지함
                매수 = False
            elif not (초당거래대금 / 초당거래대금평균(30) > 2.5):
                매수 = False
            elif not (초당매수수량 > 매도총잔량 * 0.20):
                매수 = False
            elif not (매도총잔량 > 매수총잔량 * 0.10 and 매도총잔량 < 매수총잔량 * 2.0):
                매수 = False
            elif not (체결강도 >= 70 and 체결강도 <= 300):
                매수 = False
        else:
            매수 = False
    else:
        매수 = False


# ---------- 09:02:00 ~ 09:05:00 (905 전략) ----------
elif 90200 <= 시분초 < 90700:
    if not (1000 < 현재가 <= 30000):
        매수 = False
    elif not (2.0 < 등락율 <= 15.0):
        매수 = False
    elif not (고저평균대비등락율 > 0):
        매수 = False
    elif not (현재가 < VI아래5호가):
        매수 = False
    elif 라운드피겨위5호가이내:
        매수 = False
    elif not (초당거래대금 > 초당거래대금N(1) * 1.0):
        매수 = False
    else:
        if 시가총액 < 3000:
            if not (0.0 <= 시가등락율 < 8.0):
                매수 = False
            elif not (3.0 <= 시가대비등락율 < 8.0):
                매수 = False
            elif not (1 < 초당순매수금액 < 1000):
                매수 = False
            elif not (현재가 > (고가 - (고가 - 저가) * 0.20)):
                매수 = False
            elif not (전일비 > 5 and 전일동시간비 > 0):
                매수 = False
            elif not (회전율 > 1.5):
                매수 = False
            elif not (당일거래대금 > 50 * 100):
                매수 = False
            elif not (당일거래대금각도(30) > 10 and 당일거래대금각도(30) < 30):
                매수 = False
            elif not (초당거래대금 / 초당거래대금평균(30) > 2.0):
                매수 = False
            elif not (초당매수수량 > 매도총잔량 * 0.30):
                매수 = False
            elif not (매도총잔량 * 0.10 < 매수총잔량 * 1.0):
                매수 = False
            elif not (누적초당매수수량(30) * 0.5 < 누적초당매도수량(30) * 1.0):
                매수 = False
            elif not (누적초당매도수량(30) * 1.0 < 누적초당매수수량(30) * 1.0):
                매수 = False
            elif not (체결강도 >= 70 and 체결강도 <= 300):
                매수 = False
        else:
            매수 = False


# ---------- 09:05:00 이후 ----------
else:
    매수 = False


# ================================
#  매수 호출
